void Rva004C1B60Adapter::populateBuildTooltipLayout(UnicodeString &name, UnicodeString &cost, UnicodeString &commandPointCost, UnicodeString &descrip)
{
    Rva004C1C30Drawable *draw = reinterpret_cast<Rva004C1C30UI *>(TheInGameUI)->slot104();
    Object *selectedObject = draw ? draw->object : 0;
    Player *localPlayer = ThePlayerList->getLocalPlayer();
    Player *player = selectedObject ? selectedObject->getControllingPlayer() : localPlayer;
    UnicodeString requires = UnicodeString::TheEmptyString, requiresList;
    bool firstRequirement = true;
    const ProductionPrerequisite *prereq;
    bool fireScienceButton = false;
    if (m_data) {
        const ThingTemplate *thingTemplate = m_data->getThingTemplate();
        const UpgradeTemplate *upgradeTemplate = m_data->getUpgradeTemplate();
        ScienceType st = SCIENCE_INVALID;
        if (m_data->getScienceVec().size() > 1) {
            for (int j = 0; j < m_data->getScienceVec().size(); ++j) {
                st = m_data->getScienceVec()[j];
                if (m_data->getCommandType() == 0x18) {
                    if (player && !player->hasScience(st)) {
                        //Purchase science case. The first science we run into that we don't have, that's the
                        //one we'll want to show!
                        break;
                    }
                } else {
                    if (player && !player->hasScience(st) && j > 0) {
                        //If we're not looking at a command button that purchases a science, then
                        //it means we are looking at a command button that can USE the science. This
                        //means we want to get the description for the previous science -- the one
                        //we can use, not purchase!
                        st = m_data->getScienceVec()[j - 1];
                    }
                    //Now that we got the science for the button that executes the science, we need
                    //to generate a simpler help text!
                    fireScienceButton = true;
                    break;
                }
            }
        } else if (m_data->getScienceVec().size() == 1) st = m_data->getScienceVec()[0];
        bool upgradeButton = m_data->getCommandType() == 5 || m_data->getCommandType() == 6 || m_data->getCommandType() == 7;
        if (m_data->getCommandType() == 0x31 && selectedObject) {
            Rva001BF670Interface *interface = selectedObject->rva001BF670();
            if (interface) {
                float costToBuild = interface->slot2C(player);
                bool complete = selectedObject->body->slot14() == 1.0f;
                bool notFaction = !selectedObject->isFactionStructure();
                if (notFaction) {
                    if (!complete) cost.format(TheGameText->fetch("TOOLTIP:Cost"), (int)costToBuild);
                } else if (selectedObject->body->slot14() == 0.0f) {
                    cost.format(TheGameText->fetch("TOOLTIP:Cost"), (int)costToBuild);
                }
            }
        }
        if (localPlayer && m_data->getCommandType() == 0x24 && m_data->specialPower) {
            Rva004C1C30SpecialPower::Override *value = m_data->specialPower->value;
            if (value && value->next) value = reinterpret_cast<Rva004C1C30SpecialPower::Override *>(reinterpret_cast<Overridable *>(value->next)->friend_getFinalOverride());
            ScienceType science = value->science;
            if (science != SCIENCE_INVALID && !localPlayer->rva000CE380(science) && !localPlayer->rva000CE3C0(science) && !TheScienceStore->playerHasRootPrereqsForScience(localPlayer, science))
                descrip = TheGameText->fetch("TOOLTIP:ScienceDisabled");
        }
        if (descrip.isEmpty() && m_data->getDescriptionLabel().isNotEmpty())
            descrip = TheGameText->fetch(m_data->getDescriptionLabel());
        if (selectedObject && upgradeTemplate && !player->hasUpgradeInProduction(upgradeTemplate) && upgradeButton) {
            //Special case: When building upgrades
            ProductionUpdateInterface *pui = selectedObject->getProductionUpdateInterface();
            if (pui && pui->getProductionCount() == 20) {
                descrip.concat(L"\n\n");
                appendWideString(descrip, TheGameText->fetch("TOOLTIP:TooltipCannotPurchaseBecauseQueueFull"));
            } else if (!reinterpret_cast<Rva004C1C30UpgradeCenter *>(TheUpgradeCenter)->canAffordUpgrade(ThePlayerList->localPlayer, upgradeTemplate, thingTemplate, false)) {
                descrip.concat(L"\n\n");
                appendWideString(descrip, TheGameText->fetch("TOOLTIP:TooltipNotEnoughMoneyToBuild"));
            }
        }
        name = TheGameText->fetch(m_data->getTextLabel().str());
        if (thingTemplate && !(upgradeTemplate && upgradeButton) && m_data->getCommandType() != 0x18 && m_data->getCommandType() != 0x32) {
            //We are either looking at building a unit or a structure that may or may not have any
            //prerequisites.

            //Format the cost only when we have to pay for it.
            if (!(thingTemplate->fieldD8 & 0x10000000)) {
                int costToBuild = thingTemplate->calcCostToBuild(player, -1);
                if (costToBuild <= 0) cost = TheGameText->fetch("TOOLTIP:CostFree");
                else cost.format(TheGameText->fetch("TOOLTIP:Cost"), costToBuild);
            }
            if (thingTemplate->commandPoints > 0)
                commandPointCost.format(TheGameText->fetch("TOOLTIP:CommandPoints"), thingTemplate->commandPoints);
            // ask each prerequisite to give us a list of the non satisfied prerequisites
            for (int i = 0; i < thingTemplate->getPrereqCount(); ++i) {
                prereq = thingTemplate->getNthPrereq(i);
                requiresList = prereq->getRequiresList(player);
                if (requiresList != UnicodeString::TheEmptyString) {
                    // make sure to put in 'returns' to space things correctly
                    if (firstRequirement) firstRequirement = false;
                    else appendWideText(requires, L", ");
                }
                requires.concat(requiresList);
            }
            if (!requires.isEmpty()) {
                UnicodeString requireFormat = TheGameText->fetch("CONTROLBAR:Requirements");
                requires.format(requireFormat.str(), requires.str());
                if (!descrip.isEmpty()) appendWideText(descrip, L"\n");
                descrip.concat(requires);
            }
        } else if (upgradeTemplate) {
            //We are looking at an upgrade purchase icon. Maybe we already purchased it?
            bool playerUpgradeButton = m_data->getCommandType() == 5;
            bool objectUpgradeButton = m_data->getCommandType() == 6;
            bool thirdUpgradeButton = m_data->getCommandType() == 7;
            bool hasUpgradeAlready = player->hasUpgradeComplete(upgradeTemplate);
            bool hasUpgradeConflict = false;
            //Check if the first selected object has the specified upgrade. 
            if (!hasUpgradeAlready && selectedObject) {
                if ((m_data->getOptions() & 0x40) && !selectedObject->hasUpgrade(upgradeTemplate) && !selectedObject->getControllingPlayer()->hasUpgradeComplete(m_data->neededUpgrade)) {
                    //See if we can fetch the "already upgraded" text for this upgrade. If not.... use the default "fill me in".
                    if (m_data->lacksPrerequisiteLabel.isNotEmpty()) descrip = TheGameText->fetch(m_data->lacksPrerequisiteLabel);
                    else descrip = TheGameText->fetch("TOOLTIP:LacksPrerequisiteUpgradeDefault");
                } else {
                    if (reinterpret_cast<Rva004C1C30UI *>(TheInGameUI)->slotF0() == 1) {
                        hasUpgradeAlready = selectedObject->hasUpgrade(upgradeTemplate);
                        if (objectUpgradeButton) hasUpgradeConflict = !selectedObject->affectedByUpgrade(upgradeTemplate);
                    } else {
                        hasUpgradeAlready = true;
                        hasUpgradeConflict = true;
                        Rva004C1C30List *list = reinterpret_cast<Rva004C1C30UI *>(TheInGameUI)->slotFC();
                        for (Rva004C1C30Node *node = list->sentinel->next; node != list->sentinel; node = node->next) {
                            if (node->drawable && node->drawable->object) {
                                Object *object = node->drawable->object;
                                if (hasUpgradeAlready) hasUpgradeAlready = object->hasUpgrade(upgradeTemplate) ? true : false;
                                if (hasUpgradeConflict) hasUpgradeConflict = !object->affectedByUpgrade(upgradeTemplate);
                                if (!hasUpgradeAlready && !hasUpgradeConflict) break;
                            }
                        }
                    }
                    if (objectUpgradeButton && hasUpgradeConflict && !hasUpgradeAlready) {
                        if (m_data->getConflictingLabel().isNotEmpty()) descrip = TheGameText->fetch(m_data->getConflictingLabel());
                        else descrip = TheGameText->fetch("TOOLTIP:HasConflictingUpgradeDefault");
                    }
                }
            }
            if (hasUpgradeAlready) {
                if (playerUpgradeButton || objectUpgradeButton || thirdUpgradeButton) {
                    //See if we can fetch the "already upgraded" text for this upgrade. If not.... use the default "fill me in".
                    if (m_data->getPurchasedLabel().isNotEmpty()) descrip = TheGameText->fetch(m_data->getPurchasedLabel());
                    else descrip = TheGameText->fetch("TOOLTIP:AlreadyUpgradedDefault");
                }
            } else {
                //Determine the cost of the upgrade.
                unsigned int costToBuild = upgradeTemplate->calcCostToBuild(player, thingTemplate);
                if (costToBuild > 0) cost.format(TheGameText->fetch("TOOLTIP:Cost"), costToBuild);
            }
        } else if (st != SCIENCE_INVALID && !fireScienceButton) {
            cost.format(TheGameText->fetch("TOOLTIP:ScienceCost"), TheScienceStore->getSciencePurchaseCost(st));
        } else if (m_data->getCommandType() == 0x2C) {
            Rva000F9450Value *values = &reinterpret_cast<Rva004C1C30PlayerView *>(player)->values;
            int index = m_data->heroIndex;
            Rva004C1C30Hero *hero = reinterpret_cast<Rva004C1C30Hero *>(values->rva000F9450(index));
            if (hero) {
                const Rva00137E80Template *heroTemplate = Rva0020AA00TheRegistry->rva00137E80(hero->templateName);
                if (heroTemplate) {
                    AsciiString label;
                    if (hero->byte38) {
                        if (heroTemplate->rva0013E4D0(label)) name.format(TheGameText->fetch("CONTROLBAR:GenericReviveHero"), TheGameText->fetch(label).str());
                        else name.format(TheGameText->fetch("CONTROLBAR:GenericReviveHero"), heroTemplate->text.str());
                        if (!heroTemplate->rva0013E470(descrip)) descrip = TheGameText->fetch("CONTROLBAR:ToolTipGenericReviveHero");
                    } else {
                        if (heroTemplate->rva0013E4D0(label)) name.format(TheGameText->fetch("CONTROLBAR:GenericRecruitHero"), TheGameText->fetch(label).str());
                        else name.format(TheGameText->fetch("CONTROLBAR:GenericRecruitHero"), heroTemplate->text.str());
                        if (!heroTemplate->rva0013E4A0(descrip)) descrip = TheGameText->fetch("CONTROLBAR:ToolTipGenericRecruitHero");
                    }
                    descrip.concat(L"\n");
                    UnicodeString level;
                    level.format(TheGameText->fetch("APT:RankLabel"), hero->valueC);
                    appendWideString(descrip, level);
                    cost.format(TheGameText->fetch("TOOLTIP:Cost"), values->rva000F9570(index));
                }
            }
        } else if (m_data->getCommandType() == 0x20 && selectedObject) {
            static int key = TheNameKeyGenerator->nameToKey("CastleBehavior");
            Rva0036E420Castle *castle = selectedObject->findModule(key);
            if (castle && castle->canUnpack(false)) cost.format(TheGameText->fetch("TOOLTIP:Cost"), castle->getUnpackCost(player));
        }
    } else if (m_window) {
        if (m_window == TheWindowManager->winGetWindowFromId(m_owner->m_buildToolTipLayout->first, TheNameKeyGenerator->nameToKey("ControlBar.wnd:MoneyDisplay"))) {
            name = TheGameText->fetch("CONTROLBAR:Money");
            descrip = TheGameText->fetch("CONTROLBAR:MoneyDescription");
        } else if (m_window == TheWindowManager->winGetWindowFromId(m_owner->m_buildToolTipLayout->first, TheNameKeyGenerator->nameToKey("ControlBar.wnd:PowerWindow"))) {
            name = TheGameText->fetch("CONTROLBAR:Power");
            descrip = TheGameText->fetch("CONTROLBAR:PowerDescription");
            Player *playerToDisplay = ThePlayerList->getLocalPlayer();
            if (playerToDisplay && &playerToDisplay->energy) {
                Energy *energy = &playerToDisplay->energy;
                descrip.format(descrip, energy->production, energy->consumption);
            } else descrip.format(descrip, 0, 0);
        } else if (m_window == TheWindowManager->winGetWindowFromId(m_owner->m_buildToolTipLayout->first, TheNameKeyGenerator->nameToKey("ControlBar.wnd:GeneralsExp"))) {
            name = TheGameText->fetch("CONTROLBAR:GeneralsExp");
            descrip = TheGameText->fetch("CONTROLBAR:GeneralsExpDescription");
        }
    }
